import { rejectEarning } from '~/client';
import type { RejectEarningRequest, RejectEarningResponse } from '~/client';

export const useRejectEarning = defineMutation(() => {
  const route = useRoute('earnings-id');
  const earningId = computed(() => route.params.id);

  const { mutateAsync: rejectEarningMutation, asyncStatus } = useMutation({
    mutation: (params: { data: RejectEarningRequest; earningId: string }): Promise<RejectEarningResponse> =>
      rejectEarning({
        composable: '$fetch',
        path: { earning_id: params.earningId },
        body: ref(params.data),
      }),
    onSuccess: async (_, params) => {
      showToastSuccess('Earning rejected successfully.');
      const queryCache = useQueryCache();
      await queryCache.invalidateQueries({ key: ['earnings-id', params.earningId] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    rejectEarningMutation,
    isRejectingEarning: computed(() => asyncStatus.value === 'loading'),
  };
});
