import type { SignaturePaymentType } from '~/client';

export const paymentType: Record<SignaturePaymentType, string> = {
  first_part: 'First Part',
  second_part: 'Second Part',
  full: 'Full',
};

export function getPaymentTypeLabel(type: SignaturePaymentType): string {
  return paymentType[type] ?? snakeCaseToCapitalizedCase(type);
}
