import { approveEarning } from '~/client';
import type { ApproveEarningRequest, ApproveEarningResponse } from '~/client';

export const useApproveEarning = defineMutation(() => {
  const { mutateAsync: approveEarningMutation, asyncStatus } = useMutation({
    mutation: (params: { data: ApproveEarningRequest; earningId: string }): Promise<ApproveEarningResponse> =>
      approveEarning({
        composable: '$fetch',
        path: { earning_id: params.earningId },
        body: ref(params.data),
      }),
    onSuccess: async (_, params) => {
      showToastSuccess('Earning approved successfully.');
      const queryCache = useQueryCache();
      await queryCache.invalidateQueries({ key: ['earnings-id', params.earningId] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    approveEarningMutation,
    isApprovingEarning: computed(() => asyncStatus.value === 'loading'),
  };
});
