import { markEarningManuallyCompleted } from '~/client';
import type { MarkEarningManuallyCompletedRequest, MarkEarningManuallyCompletedResponse } from '~/client';

export const usePayManually = defineMutation(() => {
  const { mutateAsync: payManuallyMutation, asyncStatus } = useMutation({
    mutation: (params: {
      data: MarkEarningManuallyCompletedRequest;
      earningId: string;
    }): Promise<MarkEarningManuallyCompletedResponse> =>
      markEarningManuallyCompleted({
        composable: '$fetch',
        path: { earning_id: params.earningId },
        body: ref(params.data),
      }),
    onSuccess: async (_, params) => {
      showToastSuccess('Earning marked as completed successfully.');
      const queryCache = useQueryCache();
      await queryCache.invalidateQueries({ key: ['earnings-id', params.earningId] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    payManuallyMutation,
    isPayingManually: computed(() => asyncStatus.value === 'loading'),
  };
});
