<template>
  <Card class="col-span-2">
    <CardContent class="flex flex-col gap-4">
      <div class="flex flex-wrap justify-between items-center gap-4">
        <LabeledValue label="Amount" value-class="line-clamp-none">
          <span
            class="text-3xl font-semibold flex flex-col flex-nowrap"
            :class="getRateTypeUi(data.rate_type).amountTextClass ?? undefined"
          >
            {{ formatAmount(data.final_total) }}
          </span>
        </LabeledValue>
        <div class="flex flex-wrap items-center gap-4">
          <LabeledEntityDate
            v-if="data.work_shift_date"
            label="Work Shift Date"
            :date="data.work_shift_date"
            date-only
          />
          <LabeledEntityDate :date="data.created_at" />
        </div>
      </div>
      <Separator />
      <div class="grid grid-cols-1 md:grid-cols-2 gap-2 sm:gap-4">
        <div class="col-span-2 grid grid-cols-1 sm:grid-cols-2 gap-4 items-baseline">
          <LabeledEntityProject v-if="data.project_id" :project-id="data.project_id" />
          <LabeledEntityUser :user-id="data.canvasser.id" />
          <LabeledEntityUser v-if="data.referral_id" label="Referral" :user-id="data.referral_id" />
          <LabeledValueIcon label="Rate Type" :icon="BanknoteIcon">
            <Badge
              v-if="getRateTypeUi(data.rate_type).badgeVariant"
              :variant="getRateTypeUi(data.rate_type).badgeVariant!"
              size="md"
              class="gap-1"
            >
              <component
                :is="getRateTypeUi(data.rate_type).icon"
                v-if="getRateTypeUi(data.rate_type).icon"
                class="size-3"
              />
              <span>{{ getRateTypeUi(data.rate_type).label }}</span>
            </Badge>
            <span v-else class="text-muted-foreground">{{ getRateTypeUi(data.rate_type).label }}</span>
          </LabeledValueIcon>
          <LabeledValueIcon
            v-if="data.assignment_type"
            label="Assignment Type"
            :icon="BriefcaseBusinessIcon"
            :value="getAssignmentType(data.assignment_type).name"
          />
          <LabeledValueIcon label="Source" :value="getEarningSourceLabel(data.source)" :icon="LayersIcon" />
          <LabeledEntityDate label="Review Deadline" :date="data.review_deadline_timestamp" :icon="CalendarClockIcon" />
          <LabeledEntityDate
            v-if="data.payroll_at"
            label="Payroll Date"
            :date="data.payroll_at"
            :icon="CalendarCheckIcon"
          />
          <LabeledValueIcon
            v-if="data.retry_count"
            label="Retry Count"
            :value="data.retry_count.toString()"
            :icon="TriangleAlertIcon"
          />
          <LabeledEntityTransaction v-if="data.transaction" :transaction="data.transaction" />
        </div>
        <template v-if="data.description">
          <Separator class="col-span-2" />
          <div class="col-span-2 flex flex-col gap-2">
            <h3 class="text-lg font-medium">Description</h3>
            <AppMarkdown :markdown="data.description" />
          </div>
        </template>
        <template v-if="data.work_shift">
          <Separator class="col-span-2" />
          <div class="col-span-2 flex flex-col gap-2">
            <h3 class="text-lg font-medium">Work Shifts</h3>
            <div class="grid md:grid-cols-2 gap-3">
              <LabeledEntityWorkShift :work-shift-id="data.work_shift.id" />
              <WorkshiftTimeDetails class="row-span-2" :data="data.work_shift" />
            </div>
          </div>
        </template>
        <Separator class="col-span-2" />
        <div v-if="data.signatures" class="col-span-2 flex flex-col gap-2">
          <h3 class="text-lg font-medium">Signatures</h3>
          <ResponsiveTable>
            <ResponsiveTableHeader>
              <ResponsiveTableHead>Id</ResponsiveTableHead>
              <ResponsiveTableHead>Payment Type</ResponsiveTableHead>
              <ResponsiveTableHead>Amount</ResponsiveTableHead>
            </ResponsiveTableHeader>
            <ResponsiveTableBody>
              <ResponsiveTableEmpty
                v-if="!data.signatures || (data.signatures && data.signatures.length === 0)"
                :colspan="6"
                :cols="4"
                :cols-sm="4"
                class="text-center"
              >
                <AppEmpty subject="signatures" variant="table" />
              </ResponsiveTableEmpty>
              <ResponsiveTableRow
                v-for="item in data.signatures"
                v-else-if="data.signatures && data.signatures.length > 0"
                :key="item.id"
                class="cursor-pointer"
                @click="onSignatureRowClick(item.id)"
              >
                <ResponsiveTableCell :cols="4" :cols-sm="4" label="Id">{{ item.id }}</ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="2" label="Payment Type">{{
                  getPaymentTypeLabel(item.payment_type)
                }}</ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="2" label="Amount" class="text-right">{{
                  formatAmount(item.amount)
                }}</ResponsiveTableCell>
              </ResponsiveTableRow>
            </ResponsiveTableBody>
          </ResponsiveTable>
        </div>
      </div>
      <div class="col-span-2 grid grid-cols-1 md:grid-cols-2 gap-4">
        <div class="flex flex-col gap-1" />
        <div>
          <div class="grid grid-cols-6 gap-2 text-right items-center">
            <span class="col-span-2 font-semibold text-sm text-nowrap">Original Total</span>
            <p class="px-4 font-semibold col-span-4">{{ formatAmount(data.total) }}</p>
            <span class="text-sm col-span-2">Adjustment</span>
            <form
              v-if="data.status === 'pending' || data.status === 'under_review'"
              id="adjustment"
              class="mx-2 col-span-4"
              @submit="onSubmit"
            >
              <FormItemWrapper name="adjustment_input">
                <template #default="{ slots }">
                  <Input
                    id="adjustment_input"
                    v-maska
                    class="text-right"
                    type="text"
                    data-maska="S0.99"
                    data-maska-tokens="0:\d:multiple|9:\d:optional|S:-:optional"
                    placeholder="e.g. -1.55 or 5"
                    v-bind="slots.componentField"
                    :disabled="isAnyMutationLoading"
                  />
                </template>
              </FormItemWrapper>
            </form>
            <p v-else class="px-4 col-span-4">{{ formatAmount(data.adjustment) }}</p>
            <span class="text-sm font-semibold col-span-2 text-nowrap">Final Total</span>
            <p class="px-4 font-semibold col-span-4">{{ formatAmount(finalTotal) }}</p>
          </div>
        </div>
      </div>
    </CardContent>
    <CardFooter v-if="isNonTerminalStatus" class="flex justify-end gap-4">
      <Dialog v-model:open="payManuallyOpened">
        <DialogTrigger as-child>
          <Button variant="outline" :disabled="isAnyMutationLoading">Mark as Completed</Button>
        </DialogTrigger>
        <DialogContent class="sm:max-w-3xl w-[95%]">
          <DialogHeader class="pt-2">
            <DialogTitle
              >Are you sure you want to
              <span class="font-semibold">mark this earning as manually completed</span>?</DialogTitle
            >
            <DialogDescription>This action cannot be undone.</DialogDescription>
          </DialogHeader>
          <div class="flex flex-col gap-1">
            <span class="font-semibold text-sm">Description<span class="text-destructive">*</span></span>
            <Textarea
              v-model="payManuallyDescription"
              placeholder="Describe what this earning is for"
              class="resize-none"
              rows="4"
              :disabled="isPayingManually"
            />
            <p v-if="payManuallyDescriptionError" class="text-sm text-destructive">
              {{ payManuallyDescriptionError }}
            </p>
          </div>
          <div class="flex flex-col gap-1">
            <span class="font-semibold text-sm">Internal Comment</span>
            <p class="text-xs text-muted-foreground">Only visible to admins and managers.</p>
            <Textarea
              v-model="payManuallyComment"
              placeholder="Add an internal comment about marking this earning as completed"
              class="resize-none"
              :disabled="isPayingManually"
            />
          </div>
          <DialogFooter>
            <DialogClose as-child>
              <Button variant="outline">Cancel</Button>
            </DialogClose>
            <Button :loading="isPayingManually" :disabled="!!payManuallyDescriptionError" @click="onPayManuallyConfirm"
              >Confirm</Button
            >
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <Dialog v-model:open="opened">
        <DialogTrigger as-child>
          <template v-if="data.status === 'pending' || data.status === 'under_review'">
            <Button variant="destructive" :disabled="isAnyMutationLoading" @click="choseAction = 'Reject'"
              >Reject</Button
            >
            <Button
              form="adjustment"
              type="submit"
              :disabled="isAnyMutationLoading"
              @click="choseAction = 'Approve & Save'"
              >Approve & Save</Button
            >
          </template>
        </DialogTrigger>
        <DialogContent class="sm:max-w-3xl w-[95%]">
          <DialogHeader class="pt-2">
            <DialogTitle
              >Are you sure you want to <span class="font-semibold">{{ choseAction }}</span> this earning
              <span v-if="choseAction === 'Approve & Save'">with {{ formatAmount(finalTotal) }} payout</span
              >?</DialogTitle
            >
            <DialogDescription
              ><span v-if="choseAction === 'Reject' && values.adjustment_input"
                >Provided adjustments will be ignored.</span
              >
              <br />This action cannot be undone.</DialogDescription
            >
          </DialogHeader>
          <div class="flex flex-col gap-1">
            <span class="font-semibold text-sm">Description<span class="text-destructive">*</span></span>
            <Textarea
              v-model="description"
              placeholder="Describe what this earning is for"
              class="resize-none"
              rows="4"
              :disabled="isApprovingEarning || isRejectingEarning"
            />
            <p v-if="descriptionError" class="text-sm text-destructive">{{ descriptionError }}</p>
          </div>
          <div class="flex flex-col gap-1">
            <span class="font-semibold text-sm">Internal Comment</span>
            <p class="text-xs text-muted-foreground">Only visible to admins and managers.</p>
            <Textarea
              v-model="comment"
              placeholder="Add an internal comment about your decision for this earning"
              class="resize-none"
              :disabled="isApprovingEarning || isRejectingEarning"
            />
          </div>
          <DialogFooter>
            <DialogClose as-child>
              <Button variant="outline">Cancel</Button>
            </DialogClose>
            <Button
              :loading="isApprovingEarning || isRejectingEarning"
              :disabled="!!descriptionError"
              @click="onConfirm"
              >Confirm</Button
            >
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <Dialog v-model:open="payNowOpened">
        <DialogTrigger as-child>
          <Button v-if="canPayNow" data-testid="earning-pay-now-button" :disabled="isAnyMutationLoading"
            >Pay Now</Button
          >
        </DialogTrigger>
        <DialogContent class="sm:max-w-xl w-[95%]">
          <DialogHeader class="pt-2">
            <DialogTitle>Are you sure you want to <span class="font-semibold">pay this earning now</span>?</DialogTitle>
            <DialogDescription
              >This will instantly send {{ formatAmount(data.final_total) }} to {{ data.canvasser.first_name }}
              {{ data.canvasser.last_name }}. This action cannot be undone.</DialogDescription
            >
          </DialogHeader>
          <DialogFooter>
            <DialogClose as-child>
              <Button variant="outline">Cancel</Button>
            </DialogClose>
            <Button :loading="isPayingNow" @click="onPayNowConfirm">Confirm</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </CardFooter>
  </Card>
</template>

<script lang="ts" setup>
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { getPaymentTypeLabel } from '~/constants/earnings/paymentType';
import { getRateTypeUi } from '~/constants/earnings/rateType';
import { getEarningSourceLabel } from '~/constants/earnings/source';
import type { EarningDetailsForAdmin, EarningDetailsForManager } from '~/client';
import {
  BanknoteIcon,
  BriefcaseBusinessIcon,
  CalendarCheckIcon,
  CalendarClockIcon,
  LayersIcon,
  TriangleAlertIcon,
} from 'lucide-vue-next';
import { Badge } from '~/components/ui/badge';
import { useApproveEarning } from '~/mutations/earnings/approve';
import { useRejectEarning } from '~/mutations/earnings/reject';
import { usePayManually } from '~/mutations/earnings/payManually';
import { usePayNow } from '~/mutations/earnings/payNow';
import LabeledEntityProject from '~/components/common/labeled-entity/LabeledEntityProject.vue';
import LabeledEntityUser from '~/components/common/labeled-entity/LabeledEntityUser.vue';
import LabeledEntityDate from '~/components/common/labeled-entity/LabeledEntityDate.vue';
import { Button } from '~/components/ui/button';
import { Textarea } from '~/components/ui/textarea';
import LabeledEntityTransaction from '~/components/common/labeled-entity/LabeledEntityTransaction.vue';
import LabeledEntityWorkShift from '~/components/common/labeled-entity/LabeledEntityWorkShift.vue';
import { getAssignmentType } from '~/constants/assignments/assignmentTypes';
//TODO: refactor earning details for both roles in separate components

interface Props {
  data: EarningDetailsForAdmin | EarningDetailsForManager;
}

const props = defineProps<Props>();

const choseAction = ref<'Approve & Save' | 'Reject' | null>(null);
const opened = ref<boolean>(false);
const comment = ref<string | undefined>(undefined);
const description = ref<string>(props.data.description ?? '');
const payManuallyOpened = ref<boolean>(false);
const payManuallyComment = ref<string | undefined>(undefined);
const payManuallyDescription = ref<string>(props.data.description ?? '');
const payNowOpened = ref<boolean>(false);

const canPayNow = computed(() => props.data.status === 'ready_for_payment' && props.data.final_total > 0);

function validateDescription(value: string): string | null {
  const trimmed = value.trim();
  if (trimmed.length < 1) return 'Description is required';
  if (trimmed.length > 5000) return 'Description must be 5000 characters or fewer';
  return null;
}

const descriptionError = computed(() => validateDescription(description.value));
const payManuallyDescriptionError = computed(() => validateDescription(payManuallyDescription.value));

watch(opened, (isOpen) => {
  if (isOpen) description.value = props.data.description ?? '';
});
watch(payManuallyOpened, (isOpen) => {
  if (isOpen) payManuallyDescription.value = props.data.description ?? '';
});

const nonTerminalStatuses = ['pending', 'under_review', 'ready_for_payment', 'failed'] as const;
const isNonTerminalStatus = computed(() => nonTerminalStatuses.includes(props.data.status as any));

const formSchema = toTypedSchema(
  z.object({
    adjustment_input: z
      .string()
      .optional()
      .refine((val) => {
        if (!val) return true;
        const numberVal = Number(val);
        return !isNaN(numberVal) && numberVal !== 0;
      }, 'Adjustment must be a valid number different than 0')
      .refine((val) => {
        if (!val) return true;
        const numberVal = Number(val);
        return numberVal >= -1000 && numberVal <= 1000;
      }, 'Adjustment must be between -1000 and 1000')
      .refine((val) => {
        if (!val) return true;
        const numberVal = Number(val);
        if (!numberVal) return true;
        return numberVal + props.data.total > 0;
      }, `Adjustment cannot reduce the final total to zero or below`),
  })
);

const { handleSubmit, values } = useForm({
  validationSchema: formSchema,
});

const onSubmit = handleSubmit(async (values) => {
  console.log('values', values);
  opened.value = true;
});

const finalTotal = computed(() => {
  const adjustment =
    props.data.status === 'pending' || props.data.status === 'under_review'
      ? values.adjustment_input
      : props.data.adjustment;
  return props.data.total + (Number(adjustment) ? Number(adjustment) : 0);
});

const { rejectEarningMutation, isRejectingEarning } = useRejectEarning();
const { approveEarningMutation, isApprovingEarning } = useApproveEarning();
const { payManuallyMutation, isPayingManually } = usePayManually();
const { payNowMutation, isPayingNow } = usePayNow();

const isAnyMutationLoading = computed(
  () => isApprovingEarning.value || isRejectingEarning.value || isPayingManually.value || isPayingNow.value
);

async function onConfirm() {
  if (descriptionError.value) return;
  const route = useRoute('earnings-id');
  const earningId = route.params.id as string;
  if (choseAction.value === 'Approve & Save') {
    const requestBody = {
      adjustment:
        values.adjustment_input && Number(values.adjustment_input.replaceAll(',', ''))
          ? Number(values.adjustment_input.replaceAll(',', ''))
          : null,
      note: comment.value ? comment.value : null,
      description: description.value.trim(),
    };
    await approveEarningMutation({ data: requestBody, earningId: earningId });
  } else if (choseAction.value === 'Reject') {
    const requestBody = {
      note: comment.value ? comment.value : null,
      description: description.value.trim(),
    };
    await rejectEarningMutation({ data: requestBody, earningId: earningId });
  }
  opened.value = false;
}

async function onPayManuallyConfirm() {
  if (payManuallyDescriptionError.value) return;
  const route = useRoute('earnings-id');
  const earningId = route.params.id as string;
  await payManuallyMutation({
    data: {
      note: payManuallyComment.value ? payManuallyComment.value : null,
      description: payManuallyDescription.value.trim(),
    },
    earningId: earningId,
  });
  payManuallyOpened.value = false;
}

async function onPayNowConfirm() {
  if (!canPayNow.value) return;
  const route = useRoute('earnings-id');
  const earningId = route.params.id as string;
  await payNowMutation({ earningId: earningId });
  payNowOpened.value = false;
}

onUnmounted(() => {
  opened.value = false;
  comment.value = undefined;
  description.value = props.data.description ?? '';
  choseAction.value = null;
  payManuallyOpened.value = false;
  payManuallyComment.value = undefined;
  payManuallyDescription.value = props.data.description ?? '';
  payNowOpened.value = false;
});

async function onSignatureRowClick(id: string) {
  await navigateTo({ name: 'verification-ballots-signatures-valid-id', params: { id } });
}
</script>
