import { getEarningDetails } from '~/client';

export const useEarningsDetails = defineQuery(() => {
  const route = useRoute('earnings-id');
  const earningId = computed(() => {
    return route.params.id?.toString() || '';
  });

  const {
    data: earning,
    error,
    isLoading,
  } = useQuery({
    key: () => ['earnings-id', earningId.value],
    query: () => getEarningDetails({ composable: '$fetch', path: { earning_id: earningId.value } }),
    staleTime: 0,
    enabled: computed(() => !!earningId.value && route.name === 'earnings-id'),
  });

  return {
    earning,
    error,
    isLoading,
    earningId,
  };
});
