import type { PayEarningResponse } from '~/client';

// Transaction statuses the backend treats as a successful disbursement (the earning is
// marked COMPLETED only for these — see payroll manager). The endpoint returns 200 even
// on a failed transfer, so the outcome is read from the response. Anything else (FAILED,
// CANCELED, REVERSED, SKIPPED, UNKNOWN, SCHEDULED, or a null status) is a failure.
export const SUCCESS_TRANSACTION_STATUSES: ReadonlyArray<PayEarningResponse['status']> = ['COMPLETED', 'PENDING'];
