<template>
  <section class="grid grid-cols-2 gap-6">
    <PageTitle title="Earning Details" class="col-span-2" show-doc />
    <div class="col-span-2 flex flex-wrap justify-between items-center gap-4">
      <GoBackButton subject="earnings" :fallback-to="{ name: 'earnings' }" />
      <Badge v-if="earning?.status" :variant="getPaymentStatusBadge(earning.status).variant">{{
        getPaymentStatusBadge(earning.status).label
      }}</Badge>
    </div>
    <Alert v-if="payrollBannerDate" variant="info" class="col-span-2">
      <CalendarClockIcon />
      <AlertTitle>Upcoming payment</AlertTitle>
      <AlertDescription>
        This earning will be paid on {{ formatDateTzToFormat(payrollBannerDate, 'MM/dd/yyyy', timezone) }}.
      </AlertDescription>
    </Alert>
    <AppLoader v-if="isLoading" class="col-span-2" subject="earning details" />
    <AppError v-else-if="error" :error="error" title="Failed to load earning details" class="col-span-2" />
    <AppEmpty v-else-if="!earning" class="col-span-2" subject="earning details" />
    <EarningsCanvasserDetails
      v-else-if="processedEaringForCanvasser"
      class="col-span-2"
      :data="processedEaringForCanvasser"
    />
    <template v-else-if="processedEarningsForManagerAdmin">
      <Alert
        v-if="processedEarningsForManagerAdmin.status === 'under_review' && processedEarningsForManagerAdmin.report_id"
        variant="destructive"
        class="col-span-2"
      >
        <TriangleAlertIcon />
        <AlertTitle>Under review due to fraud detection</AlertTitle>
        <AlertDescription>
          This earning is currently under review due to a fraud report. It should be confirmed or rejected manually.
          Review deadline:
          {{ formatDateBasedOnType(processedEarningsForManagerAdmin.review_deadline_timestamp, timezone) }}
        </AlertDescription>
        <NuxtLink
          :to="{ name: 'reports-id', params: { id: processedEarningsForManagerAdmin.report_id } }"
          class="block mt-2"
        >
          <Button variant="destructive" size="sm">
            <FileWarningIcon class="size-4" />
            View Report
          </Button>
        </NuxtLink>
      </Alert>
      <Alert v-if="processedEarningsForManagerAdmin.approved_details" variant="success" class="col-span-2">
        <CircleCheckIcon />
        <AlertTitle>Approved</AlertTitle>
        <AlertDescription>
          This earning was approved by
          <InlineEntityUser :user-id="processedEarningsForManagerAdmin.approved_details.user_id" /> on
          {{ formatDateBasedOnType(processedEarningsForManagerAdmin.approved_details.timestamp, timezone) }}.
          <template v-if="processedEarningsForManagerAdmin.approved_details.comment">
            <br />
            Comment: {{ processedEarningsForManagerAdmin.approved_details.comment }}</template
          >
        </AlertDescription>
      </Alert>
      <Alert v-if="processedEarningsForManagerAdmin.cancelled_details" variant="destructive" class="col-span-2">
        <TriangleAlertIcon />
        <AlertTitle>Rejected</AlertTitle>
        <AlertDescription>
          This earning was rejected by
          <InlineEntityUser :user-id="processedEarningsForManagerAdmin.cancelled_details.user_id" /> on
          {{ formatDateBasedOnType(processedEarningsForManagerAdmin.cancelled_details.timestamp, timezone) }}.
          <template v-if="processedEarningsForManagerAdmin.cancelled_details.comment">
            <br />
            Comment: {{ processedEarningsForManagerAdmin.cancelled_details.comment }}</template
          >
        </AlertDescription>
      </Alert>
      <Alert v-if="processedEarningsForManagerAdmin.manually_completed_details" variant="info" class="col-span-2">
        <TriangleAlertIcon />
        <AlertTitle>Manually completed</AlertTitle>
        <AlertDescription>
          This earning was manually completed by
          <InlineEntityUser :user-id="processedEarningsForManagerAdmin.manually_completed_details.user_id" /> on
          {{ formatDateBasedOnType(processedEarningsForManagerAdmin.manually_completed_details.timestamp, timezone) }}.
          <template v-if="processedEarningsForManagerAdmin.manually_completed_details.comment">
            <br />
            Comment: {{ processedEarningsForManagerAdmin.manually_completed_details.comment }}</template
          >
        </AlertDescription>
      </Alert>
      <EarningsAdminManagerDetails class="col-span-2" :data="processedEarningsForManagerAdmin" />
    </template>
  </section>
</template>
<script setup lang="ts">
import { getPaymentStatusBadge } from '~/constants/earnings/paymentStatus';
import type { EarningDetailsForCanvasser, EarningDetailsForAdmin, EarningDetailsForManager } from '~/client';
import { useEarningsDetails } from '~/queries/earnings/earningDetails';
import InlineEntityUser from '~/components/common/labeled-entity/InlineEntityUser.vue';
import { formatDateBasedOnType } from '~/utils/formatDateToFormat';
import { TriangleAlertIcon, CircleCheckIcon, FileWarningIcon, CalendarClockIcon } from 'lucide-vue-next';

//TODO:test GoBackButton correctness when /earnings page will have filters
useHead({
  title: 'Earning Details',
});

definePageMeta({
  roles: ['admin', 'manager', 'canvasser'],
  backLabel: 'earning',
});

const { earning, error, isLoading } = useEarningsDetails();

const processedEaringForCanvasser = computed((): EarningDetailsForCanvasser | null => {
  return earning.value && isEarningDetailsForCanvasser(earning.value) ? earning.value : null;
});

const processedEarningsForManagerAdmin = computed((): EarningDetailsForAdmin | EarningDetailsForManager | null => {
  return earning.value && isEarningDetailsForAdminManager(earning.value) ? earning.value : null;
});
const { timezone } = useUserRole();

// Show an upcoming-payment banner to canvassers for earnings that are not yet paid.
const payrollBannerDate = computed((): string | null => {
  const canvasserEarning = processedEaringForCanvasser.value;
  if (!canvasserEarning?.payroll_at) return null;
  if (canvasserEarning.status !== 'pending' && canvasserEarning.status !== 'ready_for_payment') return null;
  return canvasserEarning.payroll_at;
});
</script>
