import { payEarningNow } from '~/client';
import type { PayEarningResponse } from '~/client';
import { SUCCESS_TRANSACTION_STATUSES } from '~/constants/earnings/transactionsStatuses';

export const usePayNow = defineMutation(() => {
  const { mutateAsync: payNowMutation, asyncStatus } = useMutation({
    mutation: (params: { earningId: string }): Promise<PayEarningResponse> =>
      payEarningNow({
        composable: '$fetch',
        path: { earning_id: params.earningId },
      }),
    onSuccess: async (data, params) => {
      const queryCache = useQueryCache();
      await queryCache.invalidateQueries({ key: ['earnings-id', params.earningId] });

      if (!SUCCESS_TRANSACTION_STATUSES.includes(data.status)) {
        showToastError(data.error_message ?? 'Payment failed.');
        return;
      }
      showToastSuccess('Payment initiated successfully.');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    payNowMutation,
    isPayingNow: computed(() => asyncStatus.value === 'loading'),
  };
});
